WITH ranked AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY dept_name, location ORDER BY budget ASC, id ASC) AS row_num FROM departments QUALIFY row_num = 1) SELECT CASE WHEN budget >= 4488000 THEN 'HIGH' ELSE 'LOW' END AS budget_tier, dept_name, SUM(CASE WHEN location = 'Tokyo' THEN budget ELSE 0 END) AS tokyo_budget, SORT_ARRAY(COLLECT_SET(dept_name)) AS dept_name_list, COUNT(*) AS cnt, ROUND(SUM(budget) / NULLIF(COUNT(CASE WHEN dept_name = 'Finance' THEN 1 END), 0), 2) AS budget_per_finance, COUNT(*) AS cnt_2, STDDEV_SAMP(budget) AS budget_stddev FROM ranked GROUP BY budget_tier, dept_name HAVING tokyo_budget < 1000000 ORDER BY budget_per_finance DESC;
